-- Six additional plant-based recipe options. FNRI ingredient-input estimates; not clinical approval.
-- Raw input quantities avoid assuming that cooked weight equals purchased raw weight.
-- Idempotent: matching names are left unchanged. No existing recipes are edited.
BEGIN;
DO $seed$
DECLARE r jsonb; recipe_id_new text; missing integer;
BEGIN
  FOR r IN SELECT value FROM jsonb_array_elements($recipes$[{"id":"rcp-plant-carrot-rice-porridge","name":"Carrot Rice Porridge","type":"Breakfast","cookTime":30,"ingredients":[{"fct_id":"0017","name":"Rice, well-milled","grams":60,"quantity":"60 g before cooking"},{"fct_id":"0312","name":"Carrot","grams":80,"quantity":"80 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":3,"quantity":"3 g before cooking"}],"steps":[{"title":"Measure ingredients","desc":"60 g Rice, well-milled; 80 g Carrot; 3 g Oil, coconut. Weigh these inputs before cooking."},{"title":"Cook with water","desc":"Rinse and chop the vegetables. Combine the measured rice and vegetables with about 400 ml plain water. Simmer until fully cooked and tender, adding water as needed. Stir in the measured coconut oil."},{"title":"Serve one portion","desc":"Serve the entire prepared batch as one serving. Nutrition is calculated from the weighed ingredient inputs. No salt, sauces or additional seasonings are included in this recorded recipe."},{"title":"Dietary review","desc":"Research recipe awaiting nutritionist review. Ingredient screening does not establish medical suitability, allergen cross-contact safety or a prescribed swallowing texture. Check product labels, preparation equipment and individual clinical requirements before use."}]},{"id":"rcp-plant-steamed-cabbage-and-carrot-rice","name":"Steamed Cabbage and Carrot Rice","type":"Lunch","cookTime":30,"ingredients":[{"fct_id":"0017","name":"Rice, well-milled","grams":75,"quantity":"75 g before cooking"},{"fct_id":"0308","name":"Cabbage, green","grams":100,"quantity":"100 g before cooking"},{"fct_id":"0312","name":"Carrot","grams":60,"quantity":"60 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":5,"quantity":"5 g before cooking"}],"steps":[{"title":"Measure ingredients","desc":"75 g Rice, well-milled; 100 g Cabbage, green; 60 g Carrot; 5 g Oil, coconut. Weigh these inputs before cooking."},{"title":"Cook with water","desc":"Rinse and chop the vegetables. Combine the measured rice and vegetables with about 400 ml plain water. Simmer until fully cooked and tender, adding water as needed. Stir in the measured coconut oil."},{"title":"Serve one portion","desc":"Serve the entire prepared batch as one serving. Nutrition is calculated from the weighed ingredient inputs. No salt, sauces or additional seasonings are included in this recorded recipe."},{"title":"Dietary review","desc":"Research recipe awaiting nutritionist review. Ingredient screening does not establish medical suitability, allergen cross-contact safety or a prescribed swallowing texture. Check product labels, preparation equipment and individual clinical requirements before use."}]},{"id":"rcp-plant-thick-carrot-and-cabbage-rice-soup","name":"Thick Carrot and Cabbage Rice Soup","type":"Dinner","cookTime":35,"ingredients":[{"fct_id":"0017","name":"Rice, well-milled","grams":60,"quantity":"60 g before cooking"},{"fct_id":"0312","name":"Carrot","grams":100,"quantity":"100 g before cooking"},{"fct_id":"0308","name":"Cabbage, green","grams":75,"quantity":"75 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":4,"quantity":"4 g before cooking"}],"steps":[{"title":"Measure ingredients","desc":"60 g Rice, well-milled; 100 g Carrot; 75 g Cabbage, green; 4 g Oil, coconut. Weigh these inputs before cooking."},{"title":"Cook with water","desc":"Rinse and chop the vegetables. Combine the measured rice and vegetables with about 400 ml plain water. Simmer until fully cooked and tender, adding water as needed. Stir in the measured coconut oil."},{"title":"Serve one portion","desc":"Serve the entire prepared batch as one serving. Nutrition is calculated from the weighed ingredient inputs. No salt, sauces or additional seasonings are included in this recorded recipe."},{"title":"Dietary review","desc":"Research recipe awaiting nutritionist review. Ingredient screening does not establish medical suitability, allergen cross-contact safety or a prescribed swallowing texture. Check product labels, preparation equipment and individual clinical requirements before use."}]},{"id":"rcp-plant-carrot-oatmeal","name":"Carrot Oatmeal","type":"Breakfast","cookTime":20,"ingredients":[{"fct_id":"0141","name":"Oats, quick-cooking","grams":50,"quantity":"50 g before cooking"},{"fct_id":"0312","name":"Carrot","grams":75,"quantity":"75 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":3,"quantity":"3 g before cooking"}],"steps":[{"title":"Measure ingredients","desc":"50 g Oats, quick-cooking; 75 g Carrot; 3 g Oil, coconut. Weigh these inputs before cooking."},{"title":"Cook with water","desc":"Rinse and chop the vegetables. Combine the measured oats and vegetables with about 250 ml plain water. Simmer until fully cooked and tender, adding water as needed. Stir in the measured coconut oil."},{"title":"Serve one portion","desc":"Serve the entire prepared batch as one serving. Nutrition is calculated from the weighed ingredient inputs. No salt, sauces or additional seasonings are included in this recorded recipe."},{"title":"Dietary review","desc":"Research recipe awaiting nutritionist review. Ingredient screening does not establish medical suitability, allergen cross-contact safety or a prescribed swallowing texture. Check product labels, preparation equipment and individual clinical requirements before use."}]},{"id":"rcp-plant-cabbage-and-carrot-oat-bowl","name":"Cabbage and Carrot Oat Bowl","type":"Lunch","cookTime":25,"ingredients":[{"fct_id":"0141","name":"Oats, quick-cooking","grams":60,"quantity":"60 g before cooking"},{"fct_id":"0308","name":"Cabbage, green","grams":100,"quantity":"100 g before cooking"},{"fct_id":"0312","name":"Carrot","grams":60,"quantity":"60 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":5,"quantity":"5 g before cooking"}],"steps":[{"title":"Measure ingredients","desc":"60 g Oats, quick-cooking; 100 g Cabbage, green; 60 g Carrot; 5 g Oil, coconut. Weigh these inputs before cooking."},{"title":"Cook with water","desc":"Rinse and chop the vegetables. Combine the measured oats and vegetables with about 250 ml plain water. Simmer until fully cooked and tender, adding water as needed. Stir in the measured coconut oil."},{"title":"Serve one portion","desc":"Serve the entire prepared batch as one serving. Nutrition is calculated from the weighed ingredient inputs. No salt, sauces or additional seasonings are included in this recorded recipe."},{"title":"Dietary review","desc":"Research recipe awaiting nutritionist review. Ingredient screening does not establish medical suitability, allergen cross-contact safety or a prescribed swallowing texture. Check product labels, preparation equipment and individual clinical requirements before use."}]},{"id":"rcp-plant-thick-vegetable-oat-soup","name":"Thick Vegetable Oat Soup","type":"Dinner","cookTime":25,"ingredients":[{"fct_id":"0141","name":"Oats, quick-cooking","grams":60,"quantity":"60 g before cooking"},{"fct_id":"0312","name":"Carrot","grams":100,"quantity":"100 g before cooking"},{"fct_id":"0308","name":"Cabbage, green","grams":50,"quantity":"50 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":4,"quantity":"4 g before cooking"}],"steps":[{"title":"Measure ingredients","desc":"60 g Oats, quick-cooking; 100 g Carrot; 50 g Cabbage, green; 4 g Oil, coconut. Weigh these inputs before cooking."},{"title":"Cook with water","desc":"Rinse and chop the vegetables. Combine the measured oats and vegetables with about 250 ml plain water. Simmer until fully cooked and tender, adding water as needed. Stir in the measured coconut oil."},{"title":"Serve one portion","desc":"Serve the entire prepared batch as one serving. Nutrition is calculated from the weighed ingredient inputs. No salt, sauces or additional seasonings are included in this recorded recipe."},{"title":"Dietary review","desc":"Research recipe awaiting nutritionist review. Ingredient screening does not establish medical suitability, allergen cross-contact safety or a prescribed swallowing texture. Check product labels, preparation equipment and individual clinical requirements before use."}]}]$recipes$::jsonb) LOOP
    IF EXISTS (SELECT 1 FROM public.recipes WHERE name = r->>'name' OR id = r->>'id') THEN CONTINUE; END IF;
    SELECT count(*) INTO missing FROM jsonb_array_elements(r->'ingredients') ingredient
      WHERE NOT EXISTS(SELECT 1 FROM public.fnri_food_composition f WHERE f.fct_id = ingredient->>'fct_id');
    IF missing > 0 THEN RAISE EXCEPTION 'Required FNRI raw ingredient missing'; END IF;
    INSERT INTO public.recipes(id,name,type,difficulty,cook_time_min,servings,cost,kcal,protein_g,carbs_g,fats_g,diet_tags,goal_tags)
      SELECT r->>'id',r->>'name',r->>'type','easy',(r->>'cookTime')::integer,1,0,
       round(sum(f.energy_kcal * (ingredient->>'grams')::numeric / 100)),
       round(sum(f.protein_g * (ingredient->>'grams')::numeric / 100),1),
       round(sum(f.available_carbohydrate_g * (ingredient->>'grams')::numeric / 100),1),
       round(sum(f.total_fat_g * (ingredient->>'grams')::numeric / 100),1),
       ARRAY['vegan','vegetarian','dairy_free']::text[], ARRAY['improve_health','maintain']::text[]
      FROM jsonb_array_elements(r->'ingredients') ingredient JOIN public.fnri_food_composition f ON f.fct_id=ingredient->>'fct_id'
      RETURNING id INTO recipe_id_new;
    INSERT INTO public.recipe_ingredients(recipe_id,fct_id,name,grams,quantity,status,sort_order)
      SELECT recipe_id_new,ingredient->>'fct_id',ingredient->>'name',(ingredient->>'grams')::numeric,ingredient->>'quantity','avail',ordinality::integer-1
      FROM jsonb_array_elements(r->'ingredients') WITH ORDINALITY AS t(ingredient,ordinality);
    INSERT INTO public.recipe_steps(recipe_id,title,description,step_order)
      SELECT recipe_id_new,step->>'title',step->>'desc',ordinality::integer-1
      FROM jsonb_array_elements(r->'steps') WITH ORDINALITY AS t(step,ordinality);
    INSERT INTO public.recipe_steps(recipe_id,title,description,step_order) VALUES(recipe_id_new,'Nutrition and costing basis','Research recipe awaiting nutritionist review. Nutrition is estimated from the listed FNRI raw ingredient inputs, not measured cooked output. Price excludes cooking water, fuel, labour and any unlisted additions. Divide the prepared batch only if you also divide the displayed portion.',99);
  END LOOP;
END $seed$;
COMMIT;
SELECT name,type,kcal FROM public.recipes WHERE id IN ('rcp-plant-carrot-rice-porridge','rcp-plant-steamed-cabbage-and-carrot-rice','rcp-plant-thick-carrot-and-cabbage-rice-soup','rcp-plant-carrot-oatmeal','rcp-plant-cabbage-and-carrot-oat-bowl','rcp-plant-thick-vegetable-oat-soup') ORDER BY type;
